package com.andye.warmod.radar;import com.andye.warmod.antiair.AntiAirMissileVariant;import com.andye.warmod.icbm.IcbmFlightPlan;import com.andye.warmod.warhead.WarheadPayloadType;import java.util.*;import net.minecraft.world.phys.Vec3;import org.jspecify.annotations.Nullable;
final class RadarTrack{final UUID trackId;final RadarTrackKind kind;final UUID ownerPlayerId;final String ownerDisplayName;final long creationGameTime;@Nullable WarheadPayloadType payloadType;@Nullable AntiAirMissileVariant interceptorVariant;@Nullable IcbmFlightPlan carrierFlightPlan;@Nullable RadarInterceptorPlanSnapshot interceptorPlan;final LinkedHashMap<UUID,RadarTerminalPlanSnapshot> terminalPlans=new LinkedHashMap<>();@Nullable UUID terminalWarheadId;@Nullable Vec3 terminalStartPosition,terminalTargetPosition;long terminalLaunchGameTime;int terminalFlightTicks;long terminalVisualSeed;@Nullable Vec3 impactPosition;long impactGameTime;float impactVisualScale;RadarTrackPhase phase;long lastStateChangeGameTime;RadarTrack(UUID id,RadarTrackKind k,UUID owner,String name,@Nullable WarheadPayloadType payload,@Nullable AntiAirMissileVariant variant,long created,@Nullable IcbmFlightPlan carrier,@Nullable RadarInterceptorPlanSnapshot interceptor,RadarTrackPhase phase){trackId=id;kind=k;ownerPlayerId=owner;ownerDisplayName=name;payloadType=payload;interceptorVariant=variant;creationGameTime=created;carrierFlightPlan=carrier;interceptorPlan=interceptor;this.phase=phase;lastStateChangeGameTime=created;}RadarTrackSnapshot snapshot(){Optional<RadarCarrierPlanSnapshot> carrier=Optional.ofNullable(carrierFlightPlan).map(p->new RadarCarrierPlanSnapshot(p.launchPosition(),p.burnoutPosition(),p.separationPosition(),p.intendedTarget(),p.launchGameTime(),p.ignitionTicks(),p.boostTicks(),p.coastTicks(),p.visualSeed()));return new RadarTrackSnapshot(trackId,kind,ownerPlayerId,ownerDisplayName,Optional.ofNullable(payloadType),Optional.ofNullable(interceptorVariant),phase,carrier,List.copyOf(terminalPlans.values()),Optional.ofNullable(interceptorPlan));}}
